window.__PREVIEW = {"cases":[{"id":"titan","kind":"case","title":"The Titan's Tumble","theme":"Profitability collapse during record demand","category":"Profitability","level":2,"minutes":30,"drills":[{"index":0,"name":"Analytical thinking"},{"index":1,"name":"Quantitative thinking"},{"index":2,"name":"Conceptual thinking"},{"index":3,"name":"Synthesis"}],"exhibits":[{"id":"titan-e1","title":"Exhibit 1: Aurelius Motors Financial & Production Data","columns":["Metric","2021 (Baseline)","2025 (Standard)","2025 (Bespoke)"],"rows":[["Model Type","Titan Standard","Titan Standard","Titan Bespoke"],["Units Produced/Sold","500","600","400"],["Average Retail Price (USD)","$250,000","$280,000","$500,000"],["Variable Cost per Unit (USD)","$150,000","$180,000","$420,000"],["R&D / Engineering Hours (per unit)","40 hours","45 hours","280 hours"],["Waitlist Duration","6 months","36 months","36 months"]],"lines":["The following table provides a comparison between the 2021 financial year (pre-bespoke boom) and the 2025 financial year (current state).","Key Definitions:","Variable Cost: Includes raw materials, artisanal labor, and third-party components.","Bespoke Division: Allows customers to request non-standard colors, interior materials, and bodywork modifications.","Engineering Hours: Reflects the time engineers spend verifying the safety and performance of custom modifications before production."]},{"id":"titan-e2","title":"Exhibit 2: Operational Complexity Analysis","columns":["Number of Unique Options","Production Lead Time (Weeks)","Yield Rate (% Defect Free)"],"rows":[["1-10 (Standard)","4","99.2%"],["11-50 (Custom Pack)","8","94.5%"],["50+ (Full Bespoke)","22","82.0%"]],"lines":["The chart below shows the correlation between the number of \"Unique Options\" offered and the \"Time-to-Production\" for vehicles at the Valerion factory."]}]},{"id":"digital","kind":"case","title":"Digital Frontier","theme":"Market entry: solo or joint venture","category":"Market entry and growth","level":2,"minutes":30,"drills":[{"index":0,"name":"Analytical thinking"},{"index":1,"name":"Quantitative thinking (market sizing)"},{"index":2,"name":"Quantitative thinking (financial trade-offs)"},{"index":3,"name":"Conceptual thinking"},{"index":4,"name":"Synthesis"}],"exhibits":[{"id":"digital-e1","title":"Exhibit 1: Oryxia Demographic & Tech Profile (2025)","columns":["Metric","Value"],"rows":[["Total Population","40,000,000"],["Percentage of Population over 18","60%"],["Banking Penetration (Adults)","20%"],["Smartphone Ownership","95%"],["Internet Connectivity (National)","75%"],["Avg. Weekly Spend per Adult (Cash)","$10.00"]],"lines":["Current Payment Landscape:","Cash: 90% of all transactions.","Mobile Top-up: 8% (People use airtime as a primitive currency).","Cards/Digital: 2% (Limited to high-end hotels in the capital city)."]},{"id":"digital-e2","title":"Exhibit 2: Entry Mode Assumptions (Year 3 Projections)","columns":["Assumption","Solo Entry","Joint Venture (w/ OryxTel)"],"rows":[["Market Share (of TAM)","10%","30%"],["Total Transaction Fee","1.0%","1.2%*"],["Revenue Share (NexusPay)","100%","50%"],["Customer Acquisition Cost","$4.50 / user","$1.20 / user"],["Infrastructure Investment","$25 Million","$5 Million (Shared)"]],"lines":["*The JV commands a higher fee due to OryxTel's massive \"Merchant Network\" (shops that accept the payment)."]},{"id":"digital-e3","title":"Exhibit 3: Consumer Sentiment Survey","columns":[],"rows":[],"lines":["\"Why don't you use digital payments?\"","\"I cannot see it\": 45% of respondents worry money will disappear if their phone breaks.","\"Fees\": 30% believe digital payments are only for the rich.","\"Acceptance\": 20% say their local grocery store only takes physical bills.","\"Privacy\": 5% don't want the government tracking their spending."]}]},{"id":"brittle","kind":"case","title":"The Brittle Bloom","theme":"Supply disruption and unit economics","category":"Crisis and turnaround","level":1,"minutes":30,"drills":[{"index":0,"name":"Analytical thinking"},{"index":1,"name":"Quantitative thinking"},{"index":2,"name":"Conceptual thinking"},{"index":3,"name":"Synthesis"}],"exhibits":[{"id":"brittle-e1","title":"Exhibit 1: Unit Economics per \"Exotic Bouquet\" (USD)","columns":["Cost Component","Old Air Route (2h)","Current Sea Route (6d)"],"rows":[["Sourcing Cost (Farm Price)","$40.00","$40.00"],["Freight Cost","$30.00","$10.00"],["Refrigeration/Storage","$5.00","$15.00"],["Average Spoilage Rate","5%","40%"],["Average Retail Price","$200.00","$200.00"]],"lines":["Operational Notes:","Spoilage: Under sea-freight, 4 out of every 10 bouquets are unsellable upon arrival due to petal wilting and \"stem-rot.\"","Logistics: Sea-freight requires specialized ethylene-scrubbing containers to slow aging during the 6-day journey."]},{"id":"brittle-e2","title":"Exhibit 2: Regional Supply Potential (Kyros Island)","columns":["Bloom Type","Local Supply (Units/Mo)","Import Requirement","Quality Score (1-10)"],"rows":[["Standard Roses","10,000","Low","8"],["Tropical Orchids","500","High","4*"],["Wildflowers","50,000","None","9"],["Exotic Lilies","0","100%","N/A"]],"lines":["The team mapped local farmers on Kyros to see if they could replace imports.","*Local orchids struggle with the soil acidity of Kyros, leading to smaller, less vibrant blooms."]},{"id":"brittle-e3","title":"Exhibit 3: Customer Sentiment Analysis (Post-Disruption)","columns":[],"rows":[],"lines":["Based on 1,000 recent reviews since the switch to sea-freight.","\"Not as Promised\": 65% of customers noted that flowers arrived with \"brown edges\" or \"drooping heads.\"","\"Price-Value Gap\": 25% stated they would rather buy from a supermarket at $30 than pay $200 for \"second-day\" quality.","\"Eco-Conscious Opportunity\": 10% mentioned they actually prefer the lower carbon footprint of the ships, provided the flowers look good."]}]},{"id":"glazed","kind":"case","title":"The Glazed Circuit","theme":"Make or buy: a $3 billion chip plant","category":"Investment decisions","level":2,"minutes":30,"drills":[{"index":0,"name":"Analytical thinking"},{"index":1,"name":"Quantitative thinking"},{"index":2,"name":"Conceptual thinking"},{"index":3,"name":"Synthesis"}],"exhibits":[{"id":"glazed-e1","title":"Exhibit 1: Foundry Economics - Make vs. Buy","columns":["Metric","Outsourcing (Buy)","In-House Fab (Make)"],"rows":[["Price / Variable Cost per Chip","$60.00","$25.00"],["Upfront Capital Investment","$0","$3,000,000,000"],["Annual Maintenance & Fixed OpEx","$0","$200,000,000"],["Expected Yield Rate","100% (Supplier absorbs defects)","90% (Industry average for new fabs)"],["Annual Supply Volume Required","80,000,000 units","80,000,000 units"]],"lines":["The team has gathered data on the current procurement costs from Xylos Foundry versus the projected costs of operating a proprietary facility in the Prism Republic.","Operational Assumptions:","Yield Rate: In a foundry, \"Yield\" is the percentage of chips that pass quality testing. A 90% yield means for every 100 chips manufactured, 10 are discarded as waste.","Construction Timeline: The fab will take 24 months to become fully operational."]},{"id":"glazed-e2","title":"Exhibit 2: Competitive Landscape & Supply Volatility","columns":["Year","Xylos Price / Chip","Supply Reliability","Aether Market Share"],"rows":[["2022","$40.00","100%","22%"],["2023","$45.00","95%","24%"],["2024","$60.00","82%","21%"],["2025 (Proj)","$75.00","75%","18% (Loss due to stockouts)"]],"lines":[]},{"id":"glazed-e3","title":"Exhibit 3: Specialized Talent Availability (Prism Republic)","columns":[],"rows":[],"lines":["Building a fab requires \"Foundry Masters\"—engineers with 10+ years of experience in silicon lithography.","Total Foundry Masters in Prism Republic: 150","Required for Aether Fab: 80","Current Employment: 140 are currently employed by the state-run defense agency.","Estimated Salary Premium Required: 40% above market to entice talent to switch."]}]},{"id":"longevity","kind":"case","title":"The Longevity Leap","theme":"Patent cliff and a new subscription model","category":"Business model change","level":3,"minutes":30,"drills":[{"index":0,"name":"Analytical thinking"},{"index":1,"name":"Quantitative thinking"},{"index":2,"name":"Conceptual thinking"},{"index":3,"name":"Synthesis"}],"exhibits":[{"id":"longevity-e1","title":"Exhibit 1: The Vitalis Patent Cliff (Current Projections)","columns":["Metric","Pre-Patent Expiry (Current)","Post-Patent Expiry (Proj)"],"rows":[["Number of Patients","1,000,000","200,000 (Loyal) / 800,000 (Generic)"],["Price per Month (Branded)","$500","$500"],["Price per Month (Generic)","N/A","$50"],["Monthly Revenue","$500 Million","$140 Million*"]],"lines":["*Includes $100M from loyalists + $40M from generic royalty/sales."]},{"id":"longevity-e2","title":"Exhibit 2: \"Aethel Elite\" Subscription Tier Assumptions","columns":["Tier Component","Traditional Vitalis","Aethel Elite Subscription"],"rows":[["Monthly Cost","$500","$1,000"],["Included Services","Drug only","Drug + Bio-testing + Health Coach"],["Variable Cost / User","$50","$300"],["Avg. Customer Retention","12 months","36 months (Target)"],["Target Demographic","Medical patients","\"Health Optimizers\" (Proactive)"]],"lines":["The CEO is proposing a premium service layer on top of the drug.","Market Note:","The \"Health Optimizer\" market in Altera is estimated at 5 million individuals, most of whom do not currently take Vitalis because they are not yet \"sick.\""]},{"id":"longevity-e3","title":"Exhibit 3: Competitive Response Analysis","columns":[],"rows":[],"lines":["The team interviewed executives from three major generic drug manufacturers regarding their 2026 plans.","Price Aggression: Generics plan to drop prices to $30/month within 24 months of entry.","Service Capability: Generic firms have zero experience in digital health, data privacy, or 1-on-1 coaching.","Pharmacy Relations: Generics have strong ties with bulk-buyers (hospitals/insurance); Aethel Elite requires a Direct-to-Consumer (DTC) approach."]}]},{"id":"knowledge","kind":"case","title":"The Knowledge Bridge","theme":"Redesigning a product employers don't value","category":"Business model change","level":1,"minutes":30,"drills":[{"index":0,"name":"Analytical thinking"},{"index":1,"name":"Quantitative thinking"},{"index":2,"name":"Conceptual thinking"},{"index":3,"name":"Synthesis"}],"exhibits":[{"id":"knowledge-e1","title":"Exhibit 1: Cost Structure & Delivery Models (Per Student)","columns":["Cost Component","Traditional Model (Current)","Simulated Model (Proposed)"],"rows":[["Tuition Fee (Fixed)","$2,500","$2,500"],["Instructor Costs","$800","$800 (-60% reduction*)"],["Content Creation","$400","$400"],["Admin & Overhead","$800","$800"],["Simulation License Fee","$0","$400"]],"lines":["*Instructors move from \"lecturing\" to \"grading/mentoring,\" allowing one instructor to handle 3x more students."]},{"id":"knowledge-e2","title":"Exhibit 2: Employer Satisfaction vs. Graduation Rates","columns":["Year","Graduation Rate","Avg. Exam Score","Employer \"Ready\" Score","Placement Rate"],"rows":[["2021","92%","88%","8.5 / 10","80%"],["2022","94%","89%","6.2 / 10","65%"],["2023","95%","91%","4.1 / 10","45%"]],"lines":[]},{"id":"knowledge-e3","title":"Exhibit 3: Skill Gap Analysis (Tech Sector Survey)","columns":[],"rows":[],"lines":["The team asked 50 CTOs in the Zoraid Basin: \"What is the #1 thing missing from junior hires?\"","Troubleshooting (55%): \"They can write code from scratch, but they can't fix someone else's broken code.\"","Tooling (25%): \"They know Python, but they've never used Jira, Git, or Docker—the tools we actually use to work.\"","Communication (15%): \"They can't explain a technical problem to a non-technical manager.\"","Math/Theory (5%): \"They are actually fine at the math; that's not the problem.\""]}]},{"id":"skyward","kind":"case","title":"Skyward Bound","theme":"Technology bet: drones or mountain trucks","category":"Investment decisions","level":2,"minutes":30,"drills":[{"index":0,"name":"Analytical thinking"},{"index":1,"name":"Quantitative thinking"},{"index":2,"name":"Conceptual thinking"},{"index":3,"name":"Synthesis"}],"exhibits":[{"id":"skyward-e1","title":"Exhibit 1: Operational Cost Profile (Per Trip)","columns":["Metric","Mountain Truck","Strato-Drone"],"rows":[["Max Payload Capacity","200 kg","20 kg"],["Avg. Speed","40 km/h","160 km/h"],["Variable Cost (Fuel/Power)","$2.00 / km","$0.50 / km"],["Labor Cost (Driver/Operator)","$40.00 / trip","$10.00 / trip"],["Maintenance Cost","High (Rough roads)","Low (No friction)"]],"lines":["Route Characteristics:","The \"Valley Loop\": A road distance of 50km is often only 15km for a drone flying \"as the crow flies\" over a ridge."]},{"id":"skyward-e2","title":"Exhibit 2: Reliability & Environmental Constraints","columns":["Condition","Truck Performance","Drone Performance"],"rows":[["Heavy Snow","Grounded / Blocked","Affected (Battery drain)"],["High Wind (>50km/h)","No impact","Grounded"],["Night Ops","Dangerous on cliffs","Fully Autonomous"],["Landing Req.","Paved/Gravel spot","2m x 2m clear zone"]],"lines":[]},{"id":"skyward-e3","title":"Exhibit 3: Customer Segments & Willingness to Pay (WTP)","columns":["Segment","Avg. Weight","WTP for 1h Delivery","% of Total Volume"],"rows":[["General Supplies","50 kg","Low (+$2.00)","70%"],["Retail / E-commerce","2 kg","Medium (+$15.00)","25%"],["Medical / Urgent","1 kg","High (+$150.00)","5%"]],"lines":[]}]},{"id":"veridian","kind":"case","title":"Veridian Vitals","theme":"Public transit turnaround with a social mission","category":"Crisis and turnaround","level":3,"minutes":30,"drills":[{"index":0,"name":"Analytical thinking"},{"index":1,"name":"Quantitative thinking"},{"index":2,"name":"Conceptual thinking"},{"index":3,"name":"Synthesis"}],"exhibits":[{"id":"veridian-e1","title":"Exhibit 1: Veriditrans Operating Profile (2024)","columns":["Metric","Current Value"],"rows":[["Avg. Daily Ridership","1,500,000"],["Standard Fare","$2.50"],["Annual Operating Days","360"],["Farebox Recovery Ratio","45%*"],["Annual Budget Deficit","$150,000,000"]],"lines":["*Farebox Recovery Ratio is the % of operating costs covered by fares; the rest is covered by city subsidies ($1.65B)."]},{"id":"veridian-e2","title":"Exhibit 2: Ridership Segmentation & Elasticity","columns":["Segment","% of Total Riders","Avg. Income","Est. Elasticity"],"rows":[["Essential Commuters","60%","Low","-0.1 (Inelastic)"],["Choice Riders","30%","Mid/High","-0.8 (Elastic)"],["Leisure/Students","10%","Low/Mid","-0.5 (Neutral)"]],"lines":["Veriditrans segments its riders into three primary groups to understand how price changes affect behavior."]},{"id":"veridian-e3","title":"Exhibit 3: Asset Monetization Benchmarks","columns":["Lever","Est. Annual Revenue (Potential)","Implementation Time"],"rows":[["Fiber-Optic Leasing","$45 Million","12 Months"],["E-commerce Hubs","$30 Million","18 Months"],["Digital Ad Displays","$15 Million","6 Months"],["Naming Rights","$5 Million","24 Months"]],"lines":["The team looked at other cities to see how they generate non-fare revenue."]}]},{"id":"elysian","kind":"case","title":"Elysian Power","theme":"Utility business model under rooftop solar","category":"Business model change","level":2,"minutes":30,"drills":[{"index":0,"name":"Analytical thinking"},{"index":1,"name":"Quantitative thinking"},{"index":2,"name":"Conceptual thinking"},{"index":3,"name":"Synthesis"}],"exhibits":[{"id":"elysian-e1","title":"Exhibit 1: Utility Cost & Pricing Structure (Nebula Isles)","columns":["Component","Cost per kWh (USD)","Description"],"rows":[["Generation (Variable)","$0.08","Fuel, plant ops, and bulk procurement."],["Transmission & Dist. (Fixed)","$0.07","Maintaining wires, poles, and transformers."],["Admin & Billing (Fixed)","$0.05","Customer service, executive, and overhead."],["Total Cost to Serve","$0.20",""],["Current Retail Price","$0.20","(Regulated Break-even Price)"]],"lines":["Customer Consumption Profiles (Annual):","Traditional Customer: Consumes 10,000 kWh from the grid.","Prosumer Customer: Consumes 10,000 kWh, generates 8,000 kWh (Solar).","Net Metering Rule: Prosumers only pay for their \"Net\" consumption (Usage - Generation)."]},{"id":"elysian-e2","title":"Exhibit 2: The \"Duck Curve\" - Grid Load vs. Solar Generation","columns":["Time of Day","Total Demand (MW)","Solar Gen (MW)","Net Grid Load (MW)"],"rows":[["12:00 AM","400","0","400"],["6:00 AM","600","50","550"],["12:00 PM","500","450","50"],["6:00 PM","900","20","880"],["10:00 PM","600","0","600"]],"lines":["The chart below depicts the net demand on Elysian's central power plants over a 24-hour period.","Operational Impact:","Elysian must ramp up 830 MW of generation in just 6 hours (from 12 PM to 6 PM) to compensate for the sun going down as people return home and turn on appliances."]},{"id":"elysian-e3","title":"Exhibit 3: Prosumer Sentiment & Market Trends","columns":[],"rows":[],"lines":["The team surveyed 2,000 households in the Nebula Isles.","Motivation: 85% of prosumers cited \"lowering my bill to near-zero\" as the #1 reason for solar.","Equity: 70% of non-solar owners feel it is \"unfair\" that their rates are rising to pay for a grid that their neighbors use for free.","Tech Readiness: 40% of solar owners would be willing to share control of their home battery with the utility in exchange for a $20/month credit."]}]},{"id":"gilded","kind":"case","title":"The Gilded Gate","theme":"Winning customers back from a dominant platform","category":"Market entry and growth","level":1,"minutes":30,"drills":[{"index":0,"name":"Analytical thinking"},{"index":1,"name":"Quantitative thinking"},{"index":2,"name":"Conceptual thinking"},{"index":3,"name":"Synthesis"}],"exhibits":[{"id":"gilded-e1","title":"Exhibit 1: Booking Channel Economics (Per Night)","columns":["Metric","Shadow Booking (OTA)","Inner Circle (Direct)"],"rows":[["Average Nightly Rate","$5,000","$5,000"],["Commission Fee","25%","0%"],["Loyalty Discount","0%","10% (Proposed)"],["Marketing Cost (per booking)","$0","$500"],["Data Ownership","No (Hidden Email)","Yes (Full CRM)"]],"lines":["Channel Mix Evolution (2022-2025):","2022: 20% OTA / 80% Direct","2023: 45% OTA / 55% Direct","2024: 60% OTA / 40% Direct"]},{"id":"gilded-e2","title":"Exhibit 2: Customer Lifetime Value (LTV) Comparison","columns":["Metric","OTA Guest","Direct Guest"],"rows":[["Avg. Number of Stays","1.2","3.5"],["Avg. Ancillary Spend (Spa/Dining)","$800 / stay","$2,100 / stay"],["Referral Rate","5%","40%"],["\"Brand Enthusiast\" Score","3 / 10","9 / 10"]],"lines":["The team tracked guests over a 3-year period to see how booking channel affects loyalty."]},{"id":"gilded-e3","title":"Exhibit 3: Guest Survey - \"Why I book via Shadow Booking\"","columns":[],"rows":[],"lines":["Survey of 500 UHNWIs who stayed at Lumina in the last 12 months.","\"It's just easier\": 55% said they already have their passport and assistant's details saved in the app.","\"Reward Portability\": 25% said they like earning \"Shadow Points\" that they can use for their children's ski trips or business travel.","\"Site Performance\": 15% noted that Lumina's official website is \"slow and difficult to use on a mobile device.\"","\"Price Match\": 5% said they thought the price was cheaper on the app (even though it's parity)."]}]},{"id":"lumen","kind":"case","title":"Lumen Cinemas","theme":"Profitability, then a subscription decision","category":"Profitability","level":2,"minutes":30,"drills":[{"index":0,"name":"Structure"},{"index":1,"name":"Diagnosis"},{"index":2,"name":"Decision"},{"index":4,"name":"Synthesis"}],"exhibits":[{"id":"lumen-pnl","title":"Lumen Cinemas: summary economics","columns":["","2 years ago","Last year"],"rows":[["Admissions","20M","16M"],["Average ticket price","$10.00","$11.00"],["Concession spend per admission","$5.00","$5.00"],["Film rental (% of ticket revenue)","50%","50%"],["Concession cost of goods (% of concession revenue)","20%","20%"],["Fixed costs","$120M","$116M"]],"lines":["Fixed costs cover rent, staff and site overheads."]},{"id":"lumen-sub","title":"Proposed subscription pass","columns":["Assumption","Value"],"rows":[["Price","$20 per month"],["Expected subscribers","300,000"],["Visits per subscriber","2 per month"],["Film rental paid to studios","$5 per subscriber visit"],["Concession margin","$4 per visit"],["Visits those subscribers make today","8 per year each"]],"lines":[]}],"model_answer":"Lumen's profit decline is a volume problem, not a margin problem. Losing 4 million admissions cost 36 million dollars, while higher prices and lower fixed costs gave back only 12 million. I would launch the pass as a pilot: on these assumptions it adds about 42 million a year, and about 35 million even if subscribers are heavy users. Before a national launch, we need to test sign-ups, the studios' agreement to 5 dollars a visit, and peak-time capacity.","answer_key":"\nTwo years ago: ticket revenue 20M × $10 = $200M; concessions 20M × $5 = $100M; revenue $300M. Film rental $100M; cost of goods $20M; fixed $120M; profit $60M.\nLast year: ticket revenue 16M × $11 = $176M; concessions 16M × $5 = $80M; revenue $256M. Film rental $88M; cost of goods $16M; fixed $116M; profit $36M.\nContribution per admission rose from $9.00 ($5 ticket + $4 concession) to $9.50 ($5.50 + $4).\nVolume effect: 4M fewer admissions × $9.00 = −$36M. Margin effect: 16M × +$0.50 = +$8M. Fixed cost saving = +$4M. Total −$24M.\nSubscription base case: fees 300k × $20 × 12 = $72M. Visits 300k × 24 = 7.2M. Rental −$36M. Concession margin +$28.8M. Lost existing contribution 300k × 8 = 2.4M visits × $9.50 = −$22.8M. Net +$42M a year.\nPivot at 4 visits a month: visits 14.4M. Rental −$72M. Concessions +$57.6M. Fees +$72M. Lost contribution −$22.8M. Net +$34.8M.\nGood candidates also note that the assumptions need testing: 300k subscribers, studio agreement to $5 a visit, capacity at peak times, and whether concession spend holds for subscribers."},{"id":"aster","kind":"case","title":"Aster Clinics","theme":"New business launch with a cannibalisation twist","category":"Market entry and growth","level":2,"minutes":30,"drills":[{"index":0,"name":"Structure"},{"index":1,"name":"Sizing and economics"},{"index":2,"name":"Sensitivity"},{"index":4,"name":"Synthesis"}],"exhibits":[{"id":"aster-market","title":"Market and service assumptions","columns":["Assumption","Value"],"rows":[["Adults in the city","5M"],["Doctor visits per adult per year","3"],["Share of visits suitable for video","20%"],["Expected Aster share of suitable visits","10%"],["Fee per consultation","$30"],["Doctor cost per consultation","$18"],["Platform and support costs","$2.4M per year"],["Upfront investment","$6M"]],"lines":[]}],"model_answer":"I would not launch the service as specified. It earns 1.2 million dollars a year, a five-year payback against a three-year hurdle, and if a quarter of visits come from Aster's own clinics it loses 300 thousand a year. The decision turns on whether those patients would leave anyway. So the next step is to test how many are at risk from competitors, and to explore an insurer partnership to add volume.","answer_key":"\nVisits 5M × 3 = 15M. Suitable 20% = 3M. Aster 10% = 300k. Revenue 300k × $30 = $9M.\nMargin per visit $30 − $18 = $12. Total margin $3.6M. Less $2.4M platform = $1.2M a year. Payback $6M / $1.2M = 5 years, which misses the 3-year hurdle.\nRequired for 3-year payback: $2M a year profit, so $4.4M margin, so about 367k visits, about 12.2% share.\nCannibalisation: 25% × 300k = 75k visits × $20 = −$1.5M. Net profit −$0.3M a year.\nIf the candidate raises an insurer deal and asks for numbers: 100k extra visits at $25 gives a $7 margin, or +$0.7M. Before cannibalisation, that makes $1.9M and a payback of about 3.2 years.\nKey judgement: cannibalisation counts only if those patients would otherwise have stayed. If competitors launch video anyway, some of that margin is lost either way."},{"id":"tidewater","kind":"case","title":"Tidewater Fulfilment","theme":"Capital investment under customer-concentration risk","category":"Investment decisions","level":3,"minutes":30,"drills":[{"index":0,"name":"Structure"},{"index":1,"name":"Calculation"},{"index":3,"name":"Beyond the numbers"},{"index":4,"name":"Synthesis"}],"exhibits":[{"id":"tidewater-options","title":"Automation options","columns":["","Full automation","Partial automation"],"rows":[["Upfront investment","$30M","$12M"],["Reduction in picking cost per order","60%","30%"],["Annual maintenance","$2.8M","$1.0M"]],"lines":["Today: 12M orders a year at $1.50 picking cost per order. Company hurdle: payback within 4 years."]}],"model_answer":"I would recommend partial automation now, with the option to expand later. It pays back in about 2.7 years, and still clears the four-year hurdle at about 3.9 years if the largest customer leaves. Full automation saves more but fails the hurdle in that case, at about 5.7 years, and the extra 18 million pays back in five years on its own. Revisit full automation once the tender is decided, and plan for workforce impact and seasonal peaks.","answer_key":"\nCurrent picking cost 12M × $1.50 = $18M.\nFull: saving $0.90 × 12M = $10.8M, less $2.8M = $8.0M a year. Payback $30M / $8.0M = 3.75 years.\nPartial: saving $0.45 × 12M = $5.4M, less $1.0M = $4.4M a year. Payback $12M / $4.4M = about 2.7 years.\nAt 9M orders. Full: $8.1M − $2.8M = $5.3M, payback about 5.7 years, fails. Partial: $4.05M − $1.0M = $3.05M, payback about 3.9 years, passes.\nIncremental view: the extra $18M for full earns an extra $3.6M a year at 12M orders, a 5-year payback on the increment. Spotting this is a mark of a strong candidate."},{"id":"fit","kind":"fit","title":"Fit & Story","theme":"Personal experience interview with deep probing","category":"Fit and personal experience","level":2,"minutes":25,"drills":[{"index":0,"name":"Opening"},{"index":1,"name":"Leadership story"},{"index":2,"name":"Conflict"},{"index":3,"name":"Failure"},{"index":4,"name":"Close"}],"exhibits":[],"model_answer":"There is no script to memorise. A strong story names one specific situation, says what you personally did rather than what the team did, gives a result with a number, and admits what you would do differently. It stays believable when probed three times, gives credit to others, and shows behaviour that has changed since.","answer_key":"No right answers. The interviewer's underlying question is whether a partner would want to work with this person through long, high-pressure days. Judge self-awareness, teamwork, leadership maturity, specificity and honesty. Push past rehearsed stories. Probe at least twice on each story, since the third answer is usually the honest one."}],"script":{"titan":[{"stage":0,"say":["Good to meet you. Let me give you the background.","Our client is Aurelius Motors, a boutique manufacturer of ultra-performance, handcrafted supercars based in the Principality of Valerion.","Their flagship model line, the \"Titan,\" is world-renowned for its engineering and exclusivity.","Aurelius currently enjoys record-breaking demand.","Their production for the next three years is entirely sold out, and the waitlist for a new vehicle continues to grow.","Despite this \"revenue boom,\" the CEO is facing a crisis: over the last four years, while total units sold have increased, the company’s net profit margin has plummeted from 18% to 6%.","The Board of Directors is questioning the CEO's leadership, and we have been brought in to identify the root causes of this margin compression and restore the firm's elite financial standing.","Why has Aurelius Motors' profitability collapsed during a period of record demand, and what strategic pivots are required to return to an 18% margin?","The CEO believes that rising raw material costs are the primary culprit.","However, we suspect the issue is more systemic.","What range of issues should we investigate to understand why margins are shrinking while sales are growing?"]},{"stage":1,"exhibit":"titan-e1","say":["The team has gathered financial data comparing the company's performance in 2021 and 2025.","Specifically, we have looked at the shift toward our 'Bespoke' division, which allows customers to customize every aspect of their vehicle.","Using the data in Exhibit 1, calculate the Total Contribution Margin for 2021 versus 2025.","What is the primary driver of the margin drop?"]},{"stage":2,"exhibit":"titan-e2","say":["Aurelius cannot simply stop offering customization; it is core to their brand identity.","However, we must fix the Bespoke division.","What creative, low-cost initiatives could the client take to improve the profitability of their customization business?"]},{"stage":3,"say":["Please summarise your findings and give your recommendation to the CEO, in under a minute."]}],"digital":[{"stage":0,"say":["Good to meet you. Let me give you the background.","Our client is NexusPay, a global leader in contactless digital transactions based in Europe.","They have successfully dominated developed markets and are now looking for high-growth opportunities in emerging economies.","They are specifically targeting Oryxia, a nation with a population of 40 million.","Oryxia is unique: while only 20% of adults have a formal bank account, over 95% of the population owns a smartphone.","Currently, the economy is 90% cash-based, but the government is pushing for a \"Digital Oryxia\" initiative.","NexusPay needs to decide how to enter Oryxia.","They are choosing between two paths: Solo Entry: Building their own brand and infrastructure from scratch.","Joint Venture (JV): Partnering with OryxTel, the state-owned telecommunications giant that already has a 70% share of the mobile market.","What key areas should NexusPay investigate to decide between a Solo Entry and a Joint Venture with OryxTel?"]},{"stage":1,"exhibit":"digital-e1","say":["Let's look at the market potential.","Please look at Exhibit 1 for demographic data.","Based on Exhibit 1, what is the estimated annual Total Addressable Market (TAM) in terms of transaction volume (USD) if NexusPay targets the 'Unbanked Smartphone' segment?"]},{"stage":2,"exhibit":"digital-e2","say":["Now we must compare the two entry modes.","Refer to Exhibit 2 for our financial assumptions.","Under the Joint Venture (JV), NexusPay shares 50% of the revenue with OryxTel but acquires customers 3x faster.","Under Solo entry, they keep 100% of revenue.","Which option yields higher Gross Profit for NexusPay in Year 3?"]},{"stage":3,"say":["The biggest hurdle in Oryxia is that people do not trust digital 'invisible' money.","They prefer physical cash.","Beyond marketing, what creative features or operational steps could NexusPay/OryxTel implement to build trust with rural, unbanked users?"]},{"stage":4,"say":["Please summarise your findings and give your recommendation to the CEO, in under a minute."]}],"brittle":[{"stage":0,"say":["Good to meet you. Let me give you the background.","Our client is Aetheria Botanicals, the premier luxury floral retailer in the island nation of Kyros.","They specialize in \"Ultra-Fresh Exotic Blooms\" sourced from the tropical mainland.","Their value proposition is a \"24-Hour Farm-to-Vase\" guarantee, which commands a 300% price premium over standard florists.","Two weeks ago, a volcanic eruption on a neighboring island grounded all regional air-freight.","Aetheria’s primary supply route—a 2-hour daily flight—is closed indefinitely.","They are currently forced to use sea-freight, which takes 6 days.","The \"24-Hour Guarantee\" is currently impossible to meet.","Customer complaints have spiked, and spoilage rates have decimated the bottom line.","How can Aetheria Botanicals survive this disruption without destroying its brand or going bankrupt?","What key factors should the team look at to determine the economic and strategic impact of switching from air-freight to sea-freight?"]},{"stage":1,"exhibit":"brittle-e1","say":["The team has analyzed the unit economics of a standard 'Exotic Bouquet.'","Please refer to Exhibit 1.","Assuming the bouquet sells for $200, compare the Profit per Bouquet under the 'Old Air Route' vs.","the 'Current Sea Route.'","By how much has the profit margin changed?"]},{"stage":2,"say":["The CEO is considering three options: 1) Keep sea-freight but lower prices, 2) Move 100% to local Kyros-grown flowers (which are less 'exotic' but very fresh), or 3) Invest in 'Cryo-Fresh' containers that can extend sea-transit life.","What are the pros and cons of these, and what other creative ideas do you have?"]},{"stage":3,"say":["Please summarise your findings and give your recommendation to the CEO, in under a minute."]}],"glazed":[{"stage":0,"say":["Good to meet you. Let me give you the background.","Our client is Aether Circuits, a world leader in high-end consumer electronics (smartphones and tablets) based in the Prism Republic.","Historically, Aether has outsourced its semiconductor (chip) manufacturing to a single strategic partner, Xylos Foundry, based in a neighboring region.","Over the last 18 months, Xylos Foundry has raised prices by 50% due to local energy shortages and increased labor costs.","Furthermore, supply has become volatile, causing Aether to miss several product launch windows.","The CEO is now considering a radical move: investing $3 Billion to build Aether’s own \"Fab\" (fabrication plant) to bring chip production in-house.","Should Aether Circuits commit to vertical integration by building its own chip foundry, or should it seek alternative external suppliers?","What are the key strategic and financial factors the CEO should consider when deciding whether to 'Make' (build a fab) or 'Buy' (continue outsourcing)?"]},{"stage":1,"exhibit":"glazed-e1","say":["The team has performed a cost analysis comparing the current outsourcing model with the proposed in-house foundry.","Please refer to Exhibit 1.","Based on an annual requirement of 80 million chips, what is the annual cost saving of moving production in-house?","Given the $3 Billion initial investment, what is the approximate payback period?"]},{"stage":2,"say":["The payback period looks attractive, but building a fab is not just about math.","What are the 'Execution Risks' that could turn this $3 Billion investment into a failure, and how might we mitigate them?"]},{"stage":3,"say":["Please summarise your findings and give your recommendation to the CEO, in under a minute."]}],"longevity":[{"stage":0,"say":["Good to meet you. Let me give you the background.","Our client is Aethel LifeSciences, a top-tier biotechnology firm based in the United Provinces of Altera.","For the last decade, their growth has been driven by a single \"blockbuster\" drug, Vitalis, which treats age-related cellular decline.","Vitalis currently accounts for 70% of Aethel's total revenue.","However, the patent for Vitalis expires in exactly 12 months.","Once generic competitors enter the market, Aethel expects the price of the drug to drop by 90%, creating a multi-billion dollar \"revenue hole.\"","The CEO wants to pivot from being a \"Drug Manufacturer\" to a \"Longevity Service Provider,\" offering a subscription-based health optimization platform.","How should Aethel LifeSciences structure this new subscription model to offset the Vitalis revenue loss, and is it financially viable to make this pivot within a year?","What are the key categories of issues we should investigate to determine if a 'Longevity-as-a-Service' model can successfully replace the revenue from a blockbuster drug?"]},{"stage":1,"exhibit":"longevity-e1","say":["The team has modeled the projected revenue loss and the potential of the new 'Aethel Elite' subscription.","Please refer to Exhibit 1.","Aethel currently has 1 million patients on Vitalis paying $500/month.","Post-patent, 80% of these patients are expected to switch to generics.","If Aethel launches 'Aethel Elite' at $1,000/month, what percentage of the remaining (non-generic) patients must they convert to the subscription to maintain their pre-patent revenue levels?"]},{"stage":2,"say":["As we saw, converting only the loyalists isn't enough.","We need to attract a broader audience to the 'Aethel Elite' platform.","What features could we add to the subscription to make it 'un-copyable' by generic drug manufacturers?"]},{"stage":3,"say":["Please summarise your findings and give your recommendation to the CEO, in under a minute."]}],"knowledge":[{"stage":0,"say":["Good to meet you. Let me give you the background.","Our client is Sapientia Ed, the leading provider of professional IT and Data Science certifications in the Zoraid Basin (a fast-growing economic region).","Sapientia Ed has excellent metrics on paper: 95% of students who start a course graduate, and student satisfaction scores are very high.","However, the \"Customer\" (the employers who hire these graduates) is unhappy.","A recent survey of the region's top 500 tech firms revealed that while Sapientia graduates know the theory, they lack \"Day-One Readiness\"—meaning they struggle with real-world troubleshooting and project management.","As a result, job placement rates have dropped from 80% to 45% in two years.","How can Sapientia Ed redesign its curriculum and delivery model to close the \"Readiness Gap\" without increasing tuition fees, which are already at the market ceiling?","What are the possible reasons why a student could have high 'Theoretical Knowledge' (passing exams) but low 'Day-One Readiness' (failing at work)?"]},{"stage":1,"exhibit":"knowledge-e1","say":["The CEO is considering replacing 50% of the video lectures with a 'Simulated Apprenticeship' platform where students solve real-world tickets.","Please refer to Exhibit 1.","Currently, a course costs $2,000 to deliver per student (Total Cost).","If Sapientia switches to the 'Simulated Model,' they save money on instructors but must pay a high licensing fee for the simulation software.","Based on Exhibit 1, what is the change in the 'Profit per Student'?","Is the move financially viable?"]},{"stage":2,"say":["Even if the simulation software is better, we still need to convince employers that our graduates are ready.","How can Sapientia 'prove' the value of its new graduates to tech firms without spending millions on advertising?"]},{"stage":3,"say":["Please summarise your findings and give your recommendation to the CEO, in under a minute."]}],"skyward":[{"stage":0,"say":["Good to meet you. Let me give you the background.","Our client is AetherLogistics, the leading freight and small-parcel carrier in the high-altitude region of Aethelgard.","Aethelgard is characterized by steep mountain ranges, deep valleys, and remote villages where traditional road infrastructure is often blocked by seasonal snow.","Currently, AetherLogistics relies on a fleet of specialized 4x4 mountain trucks.","However, the CEO is obsessed with \"Strato-Drones\"—heavy-lift autonomous drones capable of flying over mountain peaks to deliver packages directly.","While the tech is promising, R&D costs have ballooned, and the board is skeptical about whether drones can ever be more than a \"niche hobby.\"","Should AetherLogistics transition its \"Final Mile\" delivery from mountain trucks to Strato-Drones, and at what scale does this transition become financially superior?","What are the primary factors the CEO should consider when comparing the long-term viability of Strato-Drones versus traditional mountain trucks?"]},{"stage":1,"exhibit":"skyward-e1","say":["The team has modeled the delivery costs for a typical remote mountain route.","Please refer to Exhibit 1.","For a 50km route, which method is currently cheaper per kilogram?","At what 'Distance' does the Drone become more cost-effective than the Truck?"]},{"stage":2,"say":["The math suggests trucks are superior for bulk.","However, AetherLogistics often delivers 'Critical Supplies' (medicine, emergency parts).","How could we rethink the business model for Strato-Drones so they aren't just 'expensive trucks'?"]},{"stage":3,"say":["Please summarise your findings and give your recommendation to the CEO, in under a minute."]}],"veridian":[{"stage":0,"say":["Good to meet you. Let me give you the background.","Our client is Veriditrans, the public transit authority for the metropolis of Veridian City.","Historically, Veriditrans was the backbone of the city, carrying 2 million passengers daily via its network of light rail and electric buses.","Since 2022, Veriditrans has faced a \"perfect storm\": ridership has stabilized at only 75% of pre-2020 levels due to permanent work-from-home shifts, while energy and labor costs have risen by 20%.","The authority currently faces a $150 Million annual budget deficit.","The city government, also facing budget constraints, has warned that they cannot increase their annual subsidy.","How can Veriditrans close its $150 Million budget gap by 2027 without disproportionately hurting low-income residents who rely on the service?","What are the possible levers—both on the revenue and cost sides—that Veriditrans should consider to close a $150M deficit?"]},{"stage":1,"exhibit":"veridian-e1","say":["The team is evaluating a proposed 20% fare increase.","Currently, a single trip costs $2.","50.","Please refer to Exhibit 1 for current ridership and cost data.","If Veriditrans raises the fare by 20%, and the 'Price Elasticity' of ridership is -0.","4 (meaning a 10% price hike causes a 4% ridership drop), what is the net impact on annual revenue?","Does this close the $150M gap?"]},{"stage":2,"say":["Raising fares by 20% might drive away the very people who need transit most.","How can Veriditrans close that last $10M gap—or even replace the fare hike—using its physical assets (stations, tunnels, land)?"]},{"stage":3,"say":["Please summarise your findings and give your recommendation to the CEO, in under a minute."]}],"elysian":[{"stage":0,"say":["Good to meet you. Let me give you the background.","Our client is Elysian Power, the sole regulated utility provider for the Nebula Isles.","Historically, Elysian has operated a centralized model: generating power at large coal and gas plants and selling it to residents through a one-way grid.","In the last five years, residential solar adoption has boomed.","30% of households are now \"Prosumers\"—customers who both consume power and generate it.","Under current \"Net Metering\" laws, Elysian must buy back excess solar power from customers at the full retail price.","This has led to two problems: 1) Revenue is shrinking as people buy less power, and 2) The grid is becoming unstable because it wasn't designed for two-way flow.","How can Elysian Power transition its business model to remain financially viable and technically stable as it moves toward a decentralized, prosumer-heavy future?","What are the primary drivers of what industry experts call the 'Utility Death Spiral' for a company like Elysian Power?"]},{"stage":1,"exhibit":"elysian-e1","say":["The team is analyzing the financial impact of 'Net Metering.'","Please refer to Exhibit 1.","Currently, Elysian loses money on every kWh a prosumer 'sells back' to the grid.","Based on the data in Exhibit 1, how much 'Uncovered Grid Cost' is a Prosumer avoiding annually compared to a Traditional customer?","If Elysian moved to a 'Grid Access Fee' model, what should the annual fee be to make the average Prosumer as profitable as a Traditional customer?"]},{"stage":2,"say":["Even if we implement a Grid Fee, customers might feel it's a 'Sun Tax' and protest.","How can Elysian Power pivot its business model to provide new value as a 'Grid-as-a-Service' platform rather than just charging for access?"]},{"stage":3,"say":["Please summarise your findings and give your recommendation to the CEO, in under a minute."]}],"gilded":[{"stage":0,"say":["Good to meet you. Let me give you the background.","Our client is Lumina Resorts, an elite hospitality group that operates seven-star undersea hotels in the Nebula Isles.","Lumina is the pinnacle of luxury; a single night costs an average of $5,000.","Historically, Lumina relied on personal travel agents and word-of-mouth.","However, in the last three years, a dominant Online Travel Agency (OTA) called \"Shadow Booking\" has captured 60% of Lumina’s total reservations.","While Shadow Booking brings in high volume, they charge a 25% commission on every stay and refuse to share guest data (emails, preferences) with Lumina.","How can Lumina Resorts reduce its dependence on Shadow Booking and increase \"Direct-to-Resort\" bookings while maintaining its ultra-luxury image?","What are the primary drivers that would lead an ultra-high-net-worth individual (UHNWI) to book a $5,000-a-night hotel through a mass-market app like Shadow Booking rather than directly with the resort?"]},{"stage":1,"exhibit":"gilded-e1","say":["The team is analyzing the economics of a new 'Inner Circle' loyalty program.","Please refer to Exhibit 1.","Currently, a 5-night stay is booked through Shadow Booking.","Under the proposed 'Inner Circle' program, Lumina would offer a 10% discount for direct bookings and spend $500 in marketing to acquire that customer directly.","Compare the Net Profit to Lumina for a 5-night stay under both scenarios.","Which is more profitable?"]},{"stage":2,"say":["Discounting a $5,000 room might feel 'cheap' and damage the Lumina brand.","What are some 'Non-Monetary' benefits Lumina could offer in its Inner Circle program that Shadow Booking could never match?"]},{"stage":3,"say":["Please summarise your findings and give your recommendation to the CEO, in under a minute."]}],"lumen":[{"stage":0,"say":["Good to meet you. Let me give you the background.","Our client is Lumen Cinemas, a mid-sized cinema chain with 40 sites. Over the past two years profit has fallen from 60 million dollars to 36 million dollars. The CEO wants to know what has happened and what to do about it.","How would you approach working out what has happened to profit?"]},{"stage":1,"say":["Let us look at the numbers. Here are the economics for both years.","What is driving the decline?"],"exhibit":"lumen-pnl"},{"stage":2,"say":["The CEO is considering a subscription pass to bring people back. Here are the assumptions.","Would it add to profit?"],"exhibit":"lumen-sub"},{"stage":3,"say":["Finance now thinks the people who sign up will be your heaviest users, at 4 visits a month.","Does that change your answer?"]},{"stage":4,"say":["The CEO has just walked in. What is your recommendation, in under a minute?"]}],"aster":[{"stage":0,"say":["Good to meet you. Here is the situation.","Our client is Aster Clinics, a private family-doctor group in a wealthy Asian city of about 5 million adults. Aster is considering launching a video-consultation service. The board wants to know whether it should go ahead. It has set a hurdle of a three-year payback on any new investment.","What would you want to understand before advising the board?"]},{"stage":1,"say":["Here are the market and service assumptions.","Does the service meet the hurdle?"],"exhibit":"aster-market"},{"stage":2,"say":["What share of suitable visits would Aster need to meet the hurdle?"]},{"stage":3,"say":["The head of clinics says a quarter of video consultations would replace visits to Aster's own clinics, which earn 20 dollars margin each.","What does that do to your answer?"]},{"stage":4,"say":["What is your recommendation to the board, in under a minute?"]}],"tidewater":[{"stage":0,"say":["Good to meet you. Here is the situation.","Our client is Tidewater Fulfilment, which picks and ships online orders for retailers. Labour is getting harder to find. The operations director wants to spend 30 million dollars automating the main warehouse. The CFO has asked us whether this is the right call.","How would you think about whether this is the right call?"]},{"stage":1,"say":["Here are the two automation options.","Which looks better?"],"exhibit":"tidewater-options"},{"stage":2,"say":["The largest customer, 25 percent of orders, has just gone out to tender.","Redo your thinking."]},{"stage":3,"say":["What else should the CFO worry about, apart from the numbers?"]},{"stage":4,"say":["What is your recommendation to the CFO, in under a minute?"]}],"fit":[{"stage":0,"say":["Good to meet you. Please introduce yourself briefly, and tell me why consulting."]},{"stage":1,"say":["Tell me about a time you led others to an outcome without formal authority."]},{"stage":2,"say":["Tell me about a serious disagreement you had with a colleague or manager."]},{"stage":3,"say":["Tell me about a real failure, and what you did differently afterwards."]},{"stage":4,"say":["What question do you have for me?"]}]},"tips":[{"has_feedback":true,"rating":"mixed","worked":"Sample tip: a good interviewer listens for a structure tailored to this client.","fix":"Add a hypothesis, and say what data would prove it.","spoken":"This is a sample tip. Add a hypothesis, and say what data would prove it."},{"has_feedback":true,"rating":"mixed","worked":"Sample tip: the numbers are only half of the answer.","fix":"Finish with the so what: what the result means for the client.","spoken":"This is a sample tip. Finish with what the result means for the client."}],"sampleReport":{"headline":"Sample results: this shows the format and is not based on your answers. The live version assesses what you actually said.","next_drill":"Sample: the live version recommends one specific exercise to do before your next session.","question_reviews":[{"skill":"SKILL0","question_asked":"Sample: the question you were asked.","rating":3,"covered":"Sample: what you did on this question.","missing":"Sample: what would have taken this answer higher."},{"skill":"SKILL1","question_asked":"Sample: the question you were asked.","rating":2,"covered":"Sample: what you did on this question.","missing":"Sample: what would have taken this answer higher."},{"skill":"SKILL2","question_asked":"Sample: the question you were asked.","rating":3,"covered":"Sample: what you did on this question.","missing":"Sample: what would have taken this answer higher."}],"grade":"At the bar","grade_rating":3,"questions_reached":3,"total_questions":null,"partial":false}};
window.__PREVIEW.cases.forEach((c) => { c.stages_named = c.drills.map((d) => d.name); });
// Runs the static preview with no server: answers the app's /api calls in the browser.
// The interviewer follows a script and the results are a labelled sample.
(() => {
  const { cases, script, tips, sampleReport } = window.__PREVIEW;
  const sessions = new Map();
  const json = (body, status = 200) => new Response(JSON.stringify(body), { status, headers: { 'content-type': 'application/json' } });
  const pause = (ms) => new Promise((r) => setTimeout(r, ms));

  function turnResponse(s, body) {
    const c = cases.find((x) => x.id === s.caseId);
    const lines = script[c.id];
    const enc = new TextEncoder();
    const stream = new ReadableStream({
      async start(ctl) {
        const send = (e, d) => ctl.enqueue(enc.encode(`event: ${e}\ndata: ${JSON.stringify(d)}\n\n`));
        await pause(650);
        if (body.text && body.feedback) {
          send('coach', tips[s.tip++ % tips.length]);
          s.coached = true;
        }
        const step = s.finishing ? null : lines[s.next];
        const last = s.drill != null ? true : s.next >= lines.length - 1;
        if (step) {
          send('stage', { index: step.stage });
          for (const text of step.say) send('sentence', { text });
          if (step.exhibit) send('exhibit', c.exhibits.find((e) => e.id === step.exhibit));
        }
        if (body.text || !step) s.answers++;
        if (s.finishing || !step) {
          send('sentence', { text: 'Thanks. That is the end of this preview interview.' });
          send('end', {});
        }
        if (last) s.finishing = true;
        s.next++;
        send('done', {});
        ctl.close();
      },
    });
    return new Response(stream, { status: 200, headers: { 'content-type': 'text/event-stream' } });
  }

  const realFetch = window.fetch.bind(window);
  window.fetch = async (url, opts = {}) => {
    const path = String(url);
    if (!path.startsWith('/api/')) return realFetch(url, opts);
    const body = opts.body ? JSON.parse(opts.body) : {};
    if (path === '/api/config') return json({ preview: true, mock: true, hasCredentials: true });
    if (path === '/api/cases') return json(cases.map(({ exhibits, model_answer, answer_key, ...rest }) => rest));
    if (path === '/api/sessions' && opts.method === 'POST') {
      const id = crypto.randomUUID();
      const lines = script[body.caseId];
      const next = body.drillStage != null ? Math.max(0, lines.findIndex((l) => l.stage === body.drillStage)) : 0;
      sessions.set(id, { id, caseId: body.caseId, drill: body.drillStage, next, tip: 0, answers: 0, started: new Date().toISOString() });
      return json({ id }, 201);
    }
    if (path === '/api/sessions') return json([]);
    const m = path.match(/^\/api\/sessions\/([\w-]+)\/(turn|end)$/);
    const s = m && sessions.get(m[1]);
    if (!s) return json({ error: 'Not found.' }, 404);
    if (m[2] === 'turn') return turnResponse(s, body);
    await pause(1400);
    const c = cases.find((x) => x.id === s.caseId);
    const report = { ...sampleReport, question_reviews: sampleReport.question_reviews.map((q, i) => ({ ...q, skill: c.stages_named[i] ?? q.skill })) };
    return json({ report, previousGrade: null, modelAnswer: c.model_answer, workedNumbers: c.answer_key?.trim() });
  };
})();
